pm.test("Status code is 200", function () {
    pm.response.to.have.status(200);
});

let data;
pm.test("Response is valid JSON", function () {
    pm.expect(function () {
        data = pm.response.json();
    }).to.not.throw();
});

pm.test("access_token is a non-empty string", function () {
    pm.expect(data).to.be.an("object");
    pm.expect(data.access_token).to.be.a("string").and.not.be.empty;
});

pm.test("token_type equals bearer", function () {
    pm.expect(data.token_type).to.eql("bearer");
});

pm.test("usuario_id is a positive integer", function () {
    pm.expect(data.usuario_id).to.be.a("number");
    pm.expect(Number.isInteger(data.usuario_id)).to.be.true;
    pm.expect(data.usuario_id).to.be.above(0);
});

pm.test("tipo equals CLIENTE", function () {
    pm.expect(data.tipo).to.eql("CLIENTE");
});

pm.test("Status code is 400", function () {
    pm.response.to.have.status(400);
});

pm.test("Content-Type is JSON when provided", function () {
    const contentType = pm.response.headers.get("Content-Type");
    if (contentType) {
        pm.expect(contentType.toLowerCase()).to.include("application/json");
    }
});

let responseJson;
pm.test("Response body is valid JSON", function () {
    pm.expect(function () {
        responseJson = pm.response.json();
    }).not.to.throw();
});

pm.test("Response contains the expected LGPD validation error", function () {
    responseJson = responseJson || pm.response.json();
    pm.expect(responseJson.error).to.eql("ERRO_DE_REQUISICAO");
    pm.expect(responseJson.message).to.eql("O aceite da LGPD é obrigatório para cadastro.");
    pm.expect(responseJson.path).to.eql("/auth/registro");
});

pm.test("Details is an empty array", function () {
    responseJson = responseJson || pm.response.json();
    pm.expect(responseJson.details).to.be.an("array").that.is.empty;
});

pm.test("Timestamp is present and valid", function () {
    responseJson = responseJson || pm.response.json();
    pm.expect(responseJson).to.have.property("timestamp");
    pm.expect(responseJson.timestamp).to.be.a("string").and.not.empty;
    pm.expect(Date.parse(responseJson.timestamp)).to.not.be.NaN;
});

pm.test("Successful POST request", function () {
    pm.expect(pm.response.code).to.be.oneOf([200, 201]);
});

pm.test("Response is valid JSON", function () {
    pm.expect(() => pm.response.json()).not.to.throw();
});

pm.test("Response data matches the submitted client", function () {
    const responseData = pm.response.json();
    let requestData;

    pm.expect(pm.request.body, "Request body is present").to.exist;
    pm.expect(pm.request.body.mode, "Request body uses raw JSON").to.eql("raw");
    pm.expect(() => {
        requestData = JSON.parse(pm.variables.replaceIn(pm.request.body.raw));
    }, "Submitted request body is valid JSON").not.to.throw();

    pm.expect(responseData.id, "id").to.be.a("number").and.to.be.above(0);
    pm.expect(responseData.nome_completo, "nome_completo").to.eql(requestData.nome_completo);
    pm.expect(responseData.email, "email").to.eql(requestData.email);
    pm.expect(responseData.cpf, "cpf").to.eql(requestData.cpf);
    pm.expect(responseData.tipo, "tipo").to.eql(requestData.tipo);
    pm.expect(responseData.pontos_fidelidade, "pontos_fidelidade").to.eql(0);
    pm.expect(responseData.unidade_id, "unidade_id").to.be.null;
});

